  ],
  "title": "\"Ser\" ou \"estar\"",
  "rule": "Use 'ser' para características permanentes ou profissões e 'estar' para estados temporários ou localização. Você usou 'ser' quando deveria indicar um estado ou lugar.",
  "contrast": [
    {
      "label": "Use 'ser' para profissões",
      "example": "Ella es médica."
    },
    {
      "label": "Use 'estar' para estados temporários",
      "example": "Yo estoy cansado."
    },
    {
      "label": "Use 'estar' para localização",
      "example": "El museo está aquí."
    }
  ],
  "drill": [
    {
      "sentence": "Nosotros ___ muy cansados hoy.",
      "answer": "estamos",
      "options": [
        "somos",
        "estamos"
      ],
      "feedback": "Como o cansaço é um estado temporário, usamos 'estamos'."
    },
    {
      "sentence": "Mi padre ___ doctor en este hospital.",
      "answer": "es",
      "options": [
        "es",
        "está"
      ],
      "feedback": "Usamos 'es' porque médico é a profissão permanente dele."
    },
    {
      "sentence": "La puerta ___ abierta ahora mismo.",
      "answer": "está",
      "options": [
        "es",
        "está"
      ],
      "feedback": "O estado da porta é temporário, por isso usamos 'está'."
    },
    {
      "sentence": "El restaurante ___ en el centro de la ciudad.",
      "answer": "está",
      "options": [
        "es",
        "está"
      ],
      "feedback": "Para indicar a localização de um lugar, usamos sempre 'está'."
    },
    {
      "sentence": "Ella ___ una persona muy inteligente.",
      "answer": "es",
      "options": [
        "es",
        "está"
      ],
      "feedback": "Ser inteligente é uma característica permanente, então usamos 'es'."
    }
  ]
}
